module fifo_mem #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 4
) (
    input  logic                    clk,

    input  logic                    we,       // write enable
    input  logic [$clog2(DEPTH)-1:0] waddr,
    input  logic [WIDTH-1:0]        wdata,

    input  logic [$clog2(DEPTH)-1:0] raddr,
    output logic [WIDTH-1:0]        rdata     // one cycle after raddr
);

    logic [WIDTH-1:0] store [0:DEPTH-1];

    // The read is written FIRST and with a non-blocking assignment, so
    // it samples what was in the array before this edge. That is what
    // makes a read of the address being written return the old word:
    // every non-blocking right-hand side in the step is evaluated
    // before any of them is applied, so the order of the two
    // statements does not matter — but reading first says the intent.
    always_ff @(posedge clk) begin
        rdata <= store[raddr];
        if (we) store[waddr] <= wdata;
    end

endmodule

module fifo #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 4
) (
    input  logic             clk,
    input  logic             rst,       // synchronous, active high

    input  logic             wr_en,
    input  logic [WIDTH-1:0] wdata,

    input  logic             rd_en,
    output logic [WIDTH-1:0] rdata,     // valid the cycle after a read

    output logic             full,
    output logic             empty
);

    localparam int AW = $clog2(DEPTH);

    logic [AW-1:0]   wptr;
    logic [AW-1:0]   rptr;
    // One bit wider than DEPTH needs, because the count reaches DEPTH.
    logic [AW:0]     count;

    // Combinational, from registered state: both flags are already
    // right in the cycle after the edge that changed the count.
    assign empty = (count == '0);
    assign full  = (count == DEPTH[AW:0]);

    wire take_w = wr_en && !full;
    wire take_r = rd_en && !empty;

    fifo_mem #(.WIDTH(WIDTH), .DEPTH(DEPTH)) store (
        .clk   (clk),
        .we    (take_w),
        .waddr (wptr),
        .wdata (wdata),
        .raddr (rptr),
        .rdata (rdata)
    );

    always_ff @(posedge clk) begin
        if (rst) begin
            wptr  <= '0;
            rptr  <= '0;
            count <= '0;
        end else begin
            if (take_w) wptr <= wptr + 1'b1;
            if (take_r) rptr <= rptr + 1'b1;
            // Both in the same cycle leaves the count where it was.
            if (take_w && !take_r)      count <= count + 1'b1;
            else if (take_r && !take_w) count <= count - 1'b1;
        end
    end

endmodule

