`timescale 1ns/1ps

// The grading testbench. Depth eight, every boundary, a reset in the
// middle, a write that is refused while full, a read that is refused
// while empty, and a simultaneous read and write.
module tb;

  localparam int W = 8;
  localparam int D = 8;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic         rst   = 1'b1;
  logic         wr_en = 1'b0;
  logic         rd_en = 1'b0;
  logic [W-1:0] wdata = '0;
  logic [W-1:0] rdata;
  logic         full;
  logic         empty;

  fifo #(.WIDTH(W), .DEPTH(D)) dut (
    .clk(clk), .rst(rst), .wr_en(wr_en), .wdata(wdata),
    .rd_en(rd_en), .rdata(rdata), .full(full), .empty(empty)
  );

  int i;
  int wrong;
  logic empty_at_reset, full_at_seven, full_at_eight;
  logic still_full_after_refused_write;
  logic empty_after_drain, still_empty_after_refused_read;
  logic [W-1:0] got;
  logic [W-1:0] sim_read;
  logic         count_held;
  logic empty_after_mid_reset;

  initial begin
    wrong = 0;

    @(negedge clk);
    empty_at_reset = empty;
    rst = 1'b0;

    // Fill it to one short of full, then to full.
    for (i = 0; i < D - 1; i = i + 1) begin
      @(negedge clk); wr_en = 1'b1; wdata = (i + 1);
    end
    @(negedge clk); wr_en = 1'b0;
    full_at_seven = full;

    @(negedge clk); wr_en = 1'b1; wdata = D;
    @(negedge clk); wr_en = 1'b0;
    full_at_eight = full;

    // A write while full changes nothing.
    @(negedge clk); wr_en = 1'b1; wdata = 8'hEE;
    @(negedge clk); wr_en = 1'b0;
    still_full_after_refused_write = full;

    // A simultaneous read and write while full: the read is taken, the
    // write is refused because it is still full on that edge, so one
    // slot frees up.
    @(negedge clk); rd_en = 1'b1; wr_en = 1'b1; wdata = 8'hDD;
    @(posedge clk); #1; sim_read = rdata;
    @(negedge clk); rd_en = 1'b0; wr_en = 1'b0;
    count_held = !full;
    if (sim_read !== 8'd1) wrong = wrong + 1;

    // Drain it, checking the order as it comes out.
    @(negedge clk); rd_en = 1'b1;
    for (i = 1; i < D; i = i + 1) begin
      @(posedge clk); #1;
      got = rdata;
      if (got !== ((i + 1) & 8'hFF)) wrong = wrong + 1;
    end
    @(negedge clk); rd_en = 1'b0;
    empty_after_drain = empty;

    // A read while empty changes nothing.
    @(negedge clk); rd_en = 1'b1;
    @(negedge clk); rd_en = 1'b0;
    still_empty_after_refused_read = empty;

    // Half fill it, reset in the middle, and it is empty again.
    @(negedge clk); wr_en = 1'b1; wdata = 8'h77;
    @(negedge clk);               wdata = 8'h88;
    @(negedge clk); wr_en = 1'b0;
    @(negedge clk); rst = 1'b1;
    @(negedge clk); rst = 1'b0;
    empty_after_mid_reset = empty;

    $display("CHECK empty_after_reset 1 %0d AT %0d", empty_at_reset, $time);
    $display("CHECK not_full_one_short 0 %0d AT %0d", full_at_seven, $time);
    $display("CHECK full_at_depth 1 %0d AT %0d", full_at_eight, $time);
    $display("CHECK write_while_full_refused 1 %0d AT %0d", still_full_after_refused_write, $time);
    $display("CHECK read_makes_room 1 %0d AT %0d", count_held, $time);
    $display("CHECK order_is_fifo 0 %0d AT %0d", wrong, $time);
    $display("CHECK empty_after_drain 1 %0d AT %0d", empty_after_drain, $time);
    $display("CHECK read_while_empty_refused 1 %0d AT %0d", still_empty_after_refused_read, $time);
    $display("CHECK reset_empties_it 1 %0d AT %0d", empty_after_mid_reset, $time);
    $display("DONE 9");
    $finish;
  end

endmodule
